let file = """{"version":3,"file":"localWebSession-BibuXVMH.js","names":[],"sources":["../../packages/account-core/src/oauthPkce.ts","../../src/platform/auth/localWeb/accessTokenIdentity.ts","../../src/platform/auth/localWeb/pendingSignIn.ts","../../src/platform/auth/localWeb/localWebAuthBridge.ts","../../src/platform/auth/localWeb/localWebTokenStore.ts","../../src/platform/auth/localWeb/localWebSession.ts"],"sourcesContent":["/**\n * Authorization code + PKCE (RFC 7636, S256 only) against the Cloud OAuth\n * server, for a browser page that signs in as a public client. Builds the\n * authorize URL, reads the redirect back, and runs the code and refresh grants\n * on `/oauth/token`. Holds no state: the caller keeps the verifier and state\n * across the redirect and owns where the tokens live.\n */\nimport type { OAuthTokenResponse } from '@comfyorg/ingest-types'\nimport {\n  zOAuthTokenError,\n  zOAuthTokenResponse\n} from '@comfyorg/ingest-types/zod'\n\nimport { timedSignal } from './core/requestTimeout.js'\n\nexport const LOCAL_WEB_CLIENT_ID = 'comfy-local-web'\n\nconst AUTHORIZE_PATH = '/oauth/authorize'\nconst TOKEN_PATH = '/oauth/token'\n/** The `comfy-cloud` resource is seeded issuer-relative at `/api`. */\nconst CLOUD_RESOURCE_PATH = '/api'\nconst DEFAULT_TOKEN_TIMEOUT_MS = 15_000\n/** 32 bytes encode to the 43-character minimum verifier length. */\nconst RANDOM_BYTES = 32\nconst LOOPBACK_HOSTS = new Set(['localhost', '127.0.0.1', '[::1]'])\n\nfunction base64Url(bytes: Uint8Array): string {\n  const binary = Array.from(bytes, (byte) => String.fromCharCode(byte)).join('')\n  return btoa(binary).replace(/\\+/g, '-').replace(/\\//g, '_').replace(/=+$/, '')\n}\n\nfunction randomToken(): string {\n  return base64Url(crypto.getRandomValues(new Uint8Array(RANDOM_BYTES)))\n}\n\nexport async function codeChallengeS256(verifier: string): Promise<string> {\n  const digest = await crypto.subtle.digest(\n    'SHA-256',\n    new TextEncoder().encode(verifier)\n  )\n  return base64Url(new Uint8Array(digest))\n}\n\nexport interface PkceRequest {\n  readonly verifier: string\n  readonly challenge: string\n  readonly state: string\n}\n\n/** A fresh verifier, its S256 challenge, and an unguessable `state`. */\nexport async function createPkceRequest(): Promise<PkceRequest> {\n  const verifier = randomToken()\n  return {\n    verifier,\n    challenge: await codeChallengeS256(verifier),\n    state: randomToken()\n  }\n}\n\n/** The redirect URI registered for a page served at `origin`. */\nexport function localRedirectUri(origin: string): string {\n  return new URL('/', origin).href\n}\n\nexport interface AuthorizeUrlOptions {\n  /** Cloud origin, e.g. `https://cloud.comfy.org`. */\n  readonly issuer: string\n  readonly clientId: string\n  readonly redirectUri: string\n  readonly challenge: string\n  readonly state: string\n}\n\n/** Where the browser navigates to sign in; never fetched. */\nexport function authorizeUrl(options: AuthorizeUrlOptions): string {\n  const url = new URL(AUTHORIZE_PATH, options.issuer)\n  url.search = new URLSearchParams({\n    response_type: 'code',\n    client_id: options.clientId,\n    redirect_uri: options.redirectUri,\n    code_challenge: options.challenge,\n    code_challenge_method: 'S256',\n    state: options.state,\n    resource: new URL(CLOUD_RESOURCE_PATH, options.issuer).href\n  }).toString()\n  return url.href\n}\n\nexport type AuthorizationResponse =\n  | { readonly kind: 'none' }\n  | { readonly kind: 'code'; readonly code: string }\n  | { readonly kind: 'denied'; readonly error: string }\n  | { readonly kind: 'state-mismatch' }\n\n/**\n * Reads the authorize redirect (RFC 6749 §4.1.2) off the page URL. A response\n * whose `state` is not the one this browser sent is never used.\n */\nexport function readAuthorizationResponse(\n  params: URLSearchParams,\n  expectedState: string | undefined\n): AuthorizationResponse {\n  const code = params.get('code')\n  const error = params.get('error')\n  if (code === null && error === null) return { kind: 'none' }\n  const state = params.get('state')\n  if (expectedState === undefined || state !== expectedState) {\n    return { kind: 'state-mismatch' }\n  }\n  if (error !== null) return { kind: 'denied', error }\n  return code\n    ? { kind: 'code', code }\n    : { kind: 'denied', error: 'invalid_request' }\n}\n\nexport interface OAuthTokens {\n  readonly accessToken: string\n  readonly refreshToken: string\n  /** Epoch milliseconds. */\n  readonly expiresAt: number\n  readonly scope: string\n}\n\n/**\n * `invalid_grant`: the code or refresh token is dead; sign in again.\n * `rejected`: any other OAuth error the server returned.\n * `unavailable`: network failure, timeout, or a response that is not OAuth.\n */\nexport type TokenFailureReason = 'invalid_grant' | 'rejected' | 'unavailable'\n\nexport type TokenResult =\n  | { readonly ok: true; readonly tokens: OAuthTokens }\n  | {\n      readonly ok: false\n      readonly reason: TokenFailureReason\n      readonly error?: string\n    }\n\nexport interface TokenRequestOptions {\n  readonly issuer: string\n  readonly clientId: string\n  readonly fetchImpl: typeof fetch\n  readonly now: () => number\n  readonly signal?: AbortSignal\n  /** Default 15s. */\n  readonly timeoutMs?: number\n}\n\nfunction toTokens(body: OAuthTokenResponse, now: number): OAuthTokens {\n  return {\n    accessToken: body.access_token,\n    refreshToken: body.refresh_token,\n    expiresAt: now + body.expires_in * 1000,\n    scope: body.scope\n  }\n}\n\nasync function readJson(response: Response): Promise<unknown> {\n  try {\n    return await response.json()\n  } catch {\n    return undefined\n  }\n}\n\nfunction classify(status: number, body: unknown, now: number): TokenResult {\n  if (status === 200) {\n    const parsed = zOAuthTokenResponse.safeParse(body)\n    return parsed.success\n      ? { ok: true, tokens: toTokens(parsed.data, now) }\n      : { ok: false, reason: 'unavailable' }\n  }\n  const error = zOAuthTokenError.safeParse(body)\n  if (status < 400 || status >= 500 || !error.success) {\n    return { ok: false, reason: 'unavailable' }\n  }\n  return {\n    ok: false,\n    reason: error.data.error === 'invalid_grant' ? 'invalid_grant' : 'rejected',\n    error: error.data.error\n  }\n}\n\nfunction tokenEndpoint(issuer: string): URL | undefined {\n  const url = new URL(TOKEN_PATH, issuer)\n  if (url.protocol === 'https:') return url\n  if (url.protocol === 'http:' && LOOPBACK_HOSTS.has(url.hostname)) return url\n  return undefined\n}\n\nasync function postTokenGrant(\n  form: Record<string, string>,\n  options: TokenRequestOptions\n): Promise<TokenResult> {\n  const { signal, release } = timedSignal(\n    options.signal,\n    options.timeoutMs ?? DEFAULT_TOKEN_TIMEOUT_MS\n  )\n  try {\n    const endpoint = tokenEndpoint(options.issuer)\n    if (!endpoint) return { ok: false, reason: 'unavailable' }\n    const response = await options.fetchImpl(endpoint.href, {\n      method: 'POST',\n      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },\n      body: new URLSearchParams({ ...form, client_id: options.clientId }),\n      signal\n    })\n    return classify(response.status, await readJson(response), options.now())\n  } catch {\n    return { ok: false, reason: 'unavailable' }\n  } finally {\n    release()\n  }\n}\n\n/** Trades the authorize redirect's code for tokens. Never throws. */\nexport function exchangeAuthorizationCode(\n  grant: {\n    readonly code: string\n    readonly verifier: string\n    readonly redirectUri: string\n  },\n  options: TokenRequestOptions\n): Promise<TokenResult> {\n  return postTokenGrant(\n    {\n      grant_type: 'authorization_code',\n      code: grant.code,\n      code_verifier: grant.verifier,\n      redirect_uri: grant.redirectUri\n    },\n    options\n  )\n}\n\n/**\n * Trades a refresh token for a new pair. The server rotates on every success\n * and revokes the family when an old one is replayed, so the caller must keep\n * only the returned refresh token. Never throws.\n */\nexport function refreshAccessToken(\n  refreshToken: string,\n  options: TokenRequestOptions\n): Promise<TokenResult> {\n  return postTokenGrant(\n    { grant_type: 'refresh_token', refresh_token: refreshToken },\n    options\n  )\n}\n","import { z } from 'zod'\n\nconst zClaims = z.object({\n  sub: z.string().min(1),\n  email: z.string().optional(),\n  workspace_id: z.string().optional()\n})\n\nexport interface AccessTokenIdentity {\n  userId: string\n  email?: string\n  workspaceId?: string\n}\n\nfunction decodeSegment(segment: string): unknown {\n  const base64 = segment.replace(/-/g, '+').replace(/_/g, '/')\n  const bytes = Uint8Array.from(atob(base64), (char) => char.charCodeAt(0))\n  return JSON.parse(new TextDecoder().decode(bytes))\n}\n\n/**\n * The account and workspace the Cloud access token was issued for, read from\n * its claims as Desktop does. Nothing here grants access: Cloud verifies the\n * signature on every request.\n */\nexport function readAccessTokenIdentity(\n  accessToken: string\n): AccessTokenIdentity | undefined {\n  const payload = accessToken.split('.').at(1)\n  if (payload === undefined) return undefined\n  let decoded: unknown\n  try {\n    decoded = decodeSegment(payload)\n  } catch {\n    return undefined\n  }\n  const claims = zClaims.safeParse(decoded)\n  if (!claims.success) return undefined\n  const { sub, email, workspace_id } = claims.data\n  return { userId: sub, email, workspaceId: workspace_id }\n}\n","import { z } from 'zod'\n\nconst PENDING_KEY = 'Comfy.LocalWebSignIn.Pending'\n\nconst zPendingSignIn = z.object({\n  verifier: z.string().min(1),\n  state: z.string().min(1)\n})\n\n/** What this tab sent to the authorize endpoint, kept across the redirect. */\nexport type PendingSignIn = z.infer<typeof zPendingSignIn>\n\ntype SessionStore = Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>\n\n/** False when storage refuses the write, so no redirect starts. */\nexport function savePendingSignIn(\n  storage: SessionStore,\n  pending: PendingSignIn\n): boolean {\n  try {\n    storage.setItem(PENDING_KEY, JSON.stringify(pending))\n    return true\n  } catch {\n    return false\n  }\n}\n\n/** Reads and forgets the pending sign-in: a verifier is good for one try. */\nexport function takePendingSignIn(\n  storage: SessionStore\n): PendingSignIn | undefined {\n  try {\n    const raw = storage.getItem(PENDING_KEY)\n    storage.removeItem(PENDING_KEY)\n    if (raw === null) return undefined\n    const parsed = zPendingSignIn.safeParse(JSON.parse(raw))\n    return parsed.success ? parsed.data : undefined\n  } catch {\n    return undefined\n  }\n}\n","import type {\n  OAuthTokens,\n  TokenFailureReason\n} from '@comfyorg/account-core/oauthPkce'\nimport {\n  LOCAL_WEB_CLIENT_ID,\n  authorizeUrl,\n  createPkceRequest,\n  exchangeAuthorizationCode,\n  localRedirectUri,\n  readAuthorizationResponse,\n  refreshAccessToken\n} from '@comfyorg/account-core/oauthPkce'\n\nimport type {\n  DesktopHostAuthBridge,\n  DesktopHostAuthState\n} from '@/platform/auth/desktopHost/desktopHostAuthBridge'\nimport { readAccessTokenIdentity } from '@/platform/auth/localWeb/accessTokenIdentity'\nimport type { LocalWebTokenStore } from '@/platform/auth/localWeb/localWebTokenStore'\nimport {\n  savePendingSignIn,\n  takePendingSignIn\n} from '@/platform/auth/localWeb/pendingSignIn'\n\nconst REFRESH_MARGIN_MS = 60_000\nconst CALLBACK_PARAMS = [\n  'code',\n  'state',\n  'error',\n  'error_description',\n  'error_uri',\n  'iss'\n]\n\ntype SignInCallbackOutcome =\n  | { kind: 'none' }\n  | { kind: 'signed_in' }\n  | {\n      kind: 'failed'\n      reason: 'state-mismatch' | 'denied' | 'invalid-token' | TokenFailureReason\n      error?: string\n    }\n\nexport interface LocalWebAuthEnvironment {\n  /** Cloud origin that runs the OAuth server. */\n  issuer: string\n  /** The page URL, which carries the authorize redirect on return. */\n  pageUrl: () => string\n  navigate: (url: string) => void\n  replaceUrl: (url: string) => void\n  sessionStorage: Pick<Storage, 'getItem' | 'setItem' | 'removeItem'>\n  tokens: LocalWebTokenStore\n  fetchImpl: typeof fetch\n  now: () => number\n}\n\nexport interface LocalWebAuthBridge extends DesktopHostAuthBridge {\n  /** Finishes a sign-in the authorize redirect brought back to this page. */\n  completeSignIn(): Promise<SignInCallbackOutcome>\n}\n\n/**\n * The Desktop auth bridge contract served from the browser itself: the page\n * signs in to Cloud with authorization code + PKCE and hands out the OAuth\n * access token as the workspace credential, exactly as Desktop does.\n */\nexport function createLocalWebAuthBridge(\n  env: LocalWebAuthEnvironment\n): LocalWebAuthBridge {\n  const listeners = new Set<(state: DesktopHostAuthState) => void>()\n  let refreshing: Promise<OAuthTokens | undefined> | undefined\n\n  const tokenOptions = () => ({\n    issuer: env.issuer,\n    clientId: LOCAL_WEB_CLIENT_ID,\n    fetchImpl: env.fetchImpl,\n    now: env.now\n  })\n\n  function currentState(): DesktopHostAuthState {\n    const tokens = env.tokens.read()\n    const identity = tokens && readAccessTokenIdentity(tokens.accessToken)\n    return identity\n      ? { status: 'signed_in', ...identity }\n      : { status: 'signed_out' }\n  }\n\n  function emit(): void {\n    const state = currentState()\n    listeners.forEach((listener) => listener(state))\n  }\n\n  function adopt(tokens: OAuthTokens): boolean {\n    if (!readAccessTokenIdentity(tokens.accessToken)) return false\n    env.tokens.write(tokens)\n    return true\n  }\n\n  function signOutLocally(): DesktopHostAuthState {\n    env.tokens.clear()\n    emit()\n    return currentState()\n  }\n\n  async function refresh(stale: OAuthTokens): Promise<OAuthTokens | undefined> {\n    const result = await refreshAccessToken(stale.refreshToken, tokenOptions())\n    if (env.tokens.read() !== stale) return undefined\n    if (result.ok && adopt(result.tokens)) return result.tokens\n    if (!result.ok && result.reason === 'unavailable') return undefined\n    signOutLocally()\n    return undefined\n  }\n\n  async function freshTokens(): Promise<OAuthTokens | undefined> {\n    const tokens = env.tokens.read()\n    if (!tokens) return undefined\n    if (tokens.expiresAt - env.now() > REFRESH_MARGIN_MS) return tokens\n    refreshing ??= refresh(tokens).finally(() => {\n      refreshing = undefined\n    })\n    return refreshing\n  }\n\n  return {\n    getState: async () => currentState(),\n\n    onChanged(callback) {\n      listeners.add(callback)\n      return () => listeners.delete(callback)\n    },\n\n    async getWorkspaceToken(workspaceId) {\n      const tokens = await freshTokens()\n      if (!tokens) return null\n      const identity = readAccessTokenIdentity(tokens.accessToken)\n      return identity?.workspaceId === workspaceId ? tokens.accessToken : null\n    },\n\n    async requestSignIn() {\n      const pkce = await createPkceRequest().catch(() => undefined)\n      if (\n        !pkce ||\n        !savePendingSignIn(env.sessionStorage, {\n          verifier: pkce.verifier,\n          state: pkce.state\n        })\n      ) {\n        return currentState()\n      }\n      env.navigate(\n        authorizeUrl({\n          issuer: env.issuer,\n          clientId: LOCAL_WEB_CLIENT_ID,\n          redirectUri: localRedirectUri(new URL(env.pageUrl()).origin),\n          challenge: pkce.challenge,\n          state: pkce.state\n        })\n      )\n      return new Promise<DesktopHostAuthState>(() => {})\n    },\n\n    signOut: async () => signOutLocally(),\n\n    async completeSignIn() {\n      const url = new URL(env.pageUrl())\n      const isRedirect =\n        url.searchParams.has('code') || url.searchParams.has('error')\n      if (!isRedirect) return { kind: 'none' }\n\n      const pending = takePendingSignIn(env.sessionStorage)\n      const response = readAuthorizationResponse(\n        url.searchParams,\n        pending?.state\n      )\n\n      CALLBACK_PARAMS.forEach((param) => url.searchParams.delete(param))\n      env.replaceUrl(url.href)\n\n      if (response.kind === 'denied') {\n        return { kind: 'failed', reason: 'denied', error: response.error }\n      }\n      if (response.kind !== 'code' || !pending) {\n        return { kind: 'failed', reason: 'state-mismatch' }\n      }\n      const result = await exchangeAuthorizationCode(\n        {\n          code: response.code,\n          verifier: pending.verifier,\n          redirectUri: localRedirectUri(url.origin)\n        },\n        tokenOptions()\n      )\n      if (!result.ok) {\n        return { kind: 'failed', reason: result.reason, error: result.error }\n      }\n      if (!adopt(result.tokens)) {\n        return { kind: 'failed', reason: 'invalid-token' }\n      }\n      emit()\n      return { kind: 'signed_in' }\n    }\n  }\n}\n","import type { OAuthTokens } from '@comfyorg/account-core/oauthPkce'\n\n/** Where this tab keeps its OAuth tokens; swapping it changes the policy. */\nexport interface LocalWebTokenStore {\n  read(): OAuthTokens | undefined\n  write(tokens: OAuthTokens): void\n  clear(): void\n}\n\n/**\n * Until refresh-token storage is decided (D3), nothing is persisted: a sign-in\n * lasts as long as this tab, and a reload asks the person to sign in again.\n */\nexport function createMemoryTokenStore(): LocalWebTokenStore {\n  let tokens: OAuthTokens | undefined\n  return {\n    read: () => tokens,\n    write: (next) => {\n      tokens = next\n    },\n    clear: () => {\n      tokens = undefined\n    }\n  }\n}\n","import { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { getComfyCloudBaseUrl } from '@/config/comfyApi'\nimport { startDesktopHostSession } from '@/platform/auth/desktopHost/desktopHostSession'\nimport type { LocalWebAuthEnvironment } from '@/platform/auth/localWeb/localWebAuthBridge'\nimport { createLocalWebAuthBridge } from '@/platform/auth/localWeb/localWebAuthBridge'\